/* Project photography and easy window controls. */
(() => {
const projects=[{id:'illumed',title:'IlluminatED',image:'assets/illumed-world.webp',type:'Learning worlds',url:'https://illumed.co.uk',caption:'Real project imagery'},{id:'trainedup',title:'TrainedUp',image:'assets/trainedup-linkedin.webp',type:'Learning & careers',url:sources.trained,caption:'LinkedIn project announcement'},{id:'testify',title:'Testify',image:'assets/testify-site.png',type:'Faith & community',url:'https://testifyhub.net',caption:'Project website screenshot'},{id:'clone-own',title:'Clone & Own',image:'assets/clone-own-linkedin.webp',type:'Build-in-public series',url:sources.clone,caption:'LinkedIn episode artwork'},{id:'spider-sense',title:'Spider-Sense AI',image:'assets/spider-sense-linkedin.webp',type:'AI & interactive play',url:sources.spider,caption:'LinkedIn demo thumbnail'}];
if(window.PlayLab)projects.push(...window.PlayLab.map(g=>({id:g.id,title:g.title,image:g.image,type:g.category.split(' / ')[0],url:g.url,caption:'Original Blender model render'})));
const close=document.createElement('button');close.id='finder-close-easy';close.className='easy-window-close';close.innerHTML='Close <span>×</span>';close.setAttribute('aria-label','Close Finder window');close.onclick=()=>closeFinder();document.querySelector('.window-bar').append(close);
const gallery=document.createElement('section');gallery.id='project-pictures';gallery.className='desktop-project-gallery';gallery.setAttribute('aria-labelledby','project-gallery-title');gallery.innerHTML=`<header><div><span>FROM THE BUILD</span><h2 id="project-gallery-title">A few windows into my work.</h2></div><button data-open="work">All projects ↗</button></header><div>${projects.map(p=>`<article><button data-picture-project="${p.id}"><img src="${p.image}" alt="${p.title}: ${p.caption}" loading="lazy"><span>${p.type}</span><h3>${p.title}</h3></button><a href="${p.url}" target="_blank" rel="noopener noreferrer">${p.caption} <span>↗</span></a></article>`).join('')}</div>`;
// The full resource collection lives in Safari, not below the desktop.
const peek=document.querySelector('.project-peek'),widget=document.createElement('section');widget.className='project-peek project-picture-widget';widget.setAttribute('aria-label','Project pictures');widget.innerHTML='<div class="peek-toolbar"><span><i></i><i></i><i></i></span><small>from the build</small></div><button id="picture-preview-open"><img id="picture-preview-image" src="assets/illumed-world.webp" alt="IlluminatED project imagery"></button><div class="peek-caption"><span id="picture-preview-type">Learning worlds</span><b id="picture-preview-title">IlluminatED</b></div><div class="picture-preview-tabs">'+projects.map((p,i)=>`<button data-picture-index="${i}" aria-label="Show ${p.title}" aria-pressed="${i===0}"><img src="${p.image}" alt="" loading="lazy"></button>`).join('')+'</div>';peek.replaceWith(widget);let selected=0;
function openProject(id){const p=projects.find(p=>p.id===id);openView('work');const card=[...document.querySelectorAll('#window-content .project-card')].find(c=>c.querySelector('h3')?.textContent===p.title);if(card){card.setAttribute('tabindex','-1');card.scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth',block:'center'});card.focus({preventScroll:true});}}
gallery.addEventListener('click',e=>{const b=e.target.closest('[data-picture-project]');if(b)openProject(b.dataset.pictureProject)});widget.addEventListener('click',e=>{const b=e.target.closest('[data-picture-index]');if(b){selected=Number(b.dataset.pictureIndex);const p=projects[selected];widget.querySelector('#picture-preview-image').src=p.image;widget.querySelector('#picture-preview-image').alt=p.title+': '+p.caption;widget.querySelector('#picture-preview-title').textContent=p.title;widget.querySelector('#picture-preview-type').textContent=p.type;widget.querySelectorAll('[data-picture-index]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.pictureIndex)===selected));}if(e.target.closest('#picture-preview-open'))openProject(projects[selected].id)});
const hint=document.createElement('button');hint.className='desktop-gallery-hint';hint.textContent='Explore everything in Safari ↗';hint.onclick=()=>window.openSafari();document.querySelector('.workspace').append(hint);
const shelf=document.createElement('nav');shelf.className='easy-window-switcher';shelf.setAttribute('aria-label','Open windows');shelf.hidden=true;document.querySelector('#desktop').append(shelf);
function sync(){const windows=[{id:'finder',label:document.querySelector('#window-title').textContent},{id:'portfolio-safari',label:'Safari'}].filter(w=>document.getElementById(w.id)?.open);shelf.hidden=!windows.length;shelf.innerHTML=windows.map(w=>`<div><button data-easy-window="${w.id}">${w.id==='finder'?'▣':'◈'} ${w.label.replace(/[<>]/g,'')} <span>Open</span></button><button data-easy-close="${w.id}" aria-label="Close ${w.id==='finder'?'Finder':'Safari'}">×</button></div>`).join('');}
shelf.onclick=e=>{const c=e.target.closest('[data-easy-close]'),w=e.target.closest('[data-easy-window]');if(c)document.querySelector(c.dataset.easyClose==='finder'?'#finder-close-easy':'#safari-close-window').click();if(w){const el=document.getElementById(w.dataset.easyWindow);window.dispatchEvent(new CustomEvent('portfolio:desktop-window',{detail:{app:w.dataset.easyWindow==='finder'?'finder':'safari'}}));el.querySelector('button').focus()}};
for(const id of ['finder','portfolio-safari'])new MutationObserver(sync).observe(document.getElementById(id),{attributes:true,attributeFilter:['open']});new MutationObserver(sync).observe(document.getElementById('window-title'),{childList:true});
document.querySelector('#finder').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='w'){e.preventDefault();e.stopPropagation();closeFinder()}});
})();
